18	
19	import org.apache.dubbo.common.config.Configuration;
20	import org.apache.dubbo.common.config.ConfigurationUtils;
21	import org.apache.dubbo.common.logger.ErrorTypeAwareLogger;
22	import org.apache.dubbo.common.logger.LoggerFactory;
23	import org.apache.dubbo.common.serialize.Cleanable;
24	import org.apache.dubbo.common.serialize.ObjectInput;
25	import org.apache.dubbo.common.utils.ArrayUtils;
26	import org.apache.dubbo.common.utils.Assert;
27	import org.apache.dubbo.common.utils.StringUtils;
28	import org.apache.dubbo.remoting.Channel;
29	import org.apache.dubbo.remoting.Codec;
30	import org.apache.dubbo.remoting.Constants;
31	import org.apache.dubbo.remoting.Decodeable;
32	import org.apache.dubbo.remoting.exchange.Response;
33	import org.apache.dubbo.remoting.transport.CodecSupport;
34	import org.apache.dubbo.rpc.AppResponse;
35	import org.apache.dubbo.rpc.Invocation;
36	import org.apache.dubbo.rpc.support.RpcUtils;
37	
38	import java.io.IOException;
39	import java.io.InputStream;
40	import java.io.OutputStream;
41	import java.lang.reflect.Type;
42	
43	import static org.apache.dubbo.common.constants.CommonConstants.SystemProperty.SERIALIZATION_SECURITY_CHECK_KEY;
44	import static org.apache.dubbo.common.constants.LoggerCodeConstants.PROTOCOL_FAILED_DECODE;
45	import static org.apache.dubbo.rpc.Constants.SERIALIZATION_ID_KEY;
46	
47	public class DecodeableRpcResult extends AppResponse implements Codec, Decodeable {
48	
49	    private static final ErrorTypeAwareLogger log = LoggerFactory.getErrorTypeAwareLogger(DecodeableRpcResult.class);
50	
51	    private final Channel channel;
52	
53	    private final byte serializationType;
54	
55	    private final InputStream inputStream;
56	
57	    private final Response response;
58	
59	    private final Invocation invocation;
60	
61	    private volatile boolean hasDecoded;
62	
63	    public DecodeableRpcResult(Channel channel, Response response, InputStream is, Invocation invocation, byte id) {
64	        Assert.notNull(channel, "channel == null");
65	        Assert.notNull(response, "response == null");
66	        Assert.notNull(is, "inputStream == null");
67	        this.channel = channel;
68	        this.response = response;
69	        this.inputStream = is;
70	        this.invocation = invocation;
71	        this.serializationType = id;
72	    }
73	
74	    @Override
75	    public void encode(Channel channel, OutputStream output, Object message) throws IOException {
76	        throw new UnsupportedOperationException();
77	    }
78	
79	    @Override
80	    public Object decode(Channel channel, InputStream input) throws IOException {
81	        if (log.isDebugEnabled()) {
82	            Thread thread = Thread.currentThread();
83	            log.debug("Decoding in thread -- [" + thread.getName() + "#" + thread.getId() + "]");
84	        }
85	
86	        int contentLength = input.available();
87	        setAttribute(Constants.CONTENT_LENGTH_KEY, contentLength);
88	
89	        // switch TCCL
90	        if (invocation != null && invocation.getServiceModel() != null) {
91	            Thread.currentThread()
92	                    .setContextClassLoader(invocation.getServiceModel().getClassLoader());
93	        }
94	        ObjectInput in = CodecSupport.getSerialization(serializationType).deserialize(channel.getUrl(), input);
95	
96	        byte flag = in.readByte();
97	        switch (flag) {
98	            case DubboCodec.RESPONSE_NULL_VALUE:
99	                break;
100	            case DubboCodec.RESPONSE_VALUE:
101	                handleValue(in);
102	                break;
103	            case DubboCodec.RESPONSE_WITH_EXCEPTION:
104	                handleException(in);
105	                break;
106	            case DubboCodec.RESPONSE_NULL_VALUE_WITH_ATTACHMENTS:
107	                handleAttachment(in);
108	                break;
109	            case DubboCodec.RESPONSE_VALUE_WITH_ATTACHMENTS:
110	                handleValue(in);
111	                handleAttachment(in);
112	                break;
113	            case DubboCodec.RESPONSE_WITH_EXCEPTION_WITH_ATTACHMENTS:
114	                handleException(in);
115	                handleAttachment(in);
116	                break;
117	            default:
118	                throw new IOException("Unknown result flag, expect '0' '1' '2' '3' '4' '5', but received: " + flag);
119	        }
120	        if (in instanceof Cleanable) {
121	            ((Cleanable) in).cleanup();
122	        }
123	        return this;
124	    }
125	
126	    @Override
127	    public void decode() throws Exception {
128	        if (!hasDecoded && channel != null && inputStream != null) {
129	            try {
130	                if (invocation != null) {
131	                    Configuration systemConfiguration = null;
132	                    try {
133	                        systemConfiguration = ConfigurationUtils.getSystemConfiguration(
134	                                channel.getUrl().getScopeModel());
135	                    } catch (Exception e) {
136	                        // Because the Environment may be destroyed during the offline process, the configuration cannot
137	                        // be obtained.
138	                        // Exceptions are ignored here, and normal decoding is guaranteed.
139	                    }
140	
141	                    if (systemConfiguration == null
142	                            || systemConfiguration.getBoolean(SERIALIZATION_SECURITY_CHECK_KEY, true)) {
143	                        Object serializationTypeObj = invocation.get(SERIALIZATION_ID_KEY);
144	                        if (serializationTypeObj != null) {
145	                            if ((byte) serializationTypeObj != serializationType) {
146	                                throw new IOException("Unexpected serialization id:" + serializationType
147	                                        + " received from network, please check if the peer send the right id.");
148	                            }
149	                        }
150	                    }
151	                }
152	
153	                decode(channel, inputStream);
154	            } catch (Throwable e) {
155	                if (log.isWarnEnabled()) {
156	                    log.warn(PROTOCOL_FAILED_DECODE, "", "", "Decode rpc result failed: " + e.getMessage(), e);
157	                }
158	                response.setStatus(Response.CLIENT_ERROR);
159	                response.setErrorMessage(StringUtils.toString(e));
160	            } finally {
161	                hasDecoded = true;
162	            }
163	        }
164	    }
165	
166	    private void handleValue(ObjectInput in) throws IOException {
167	        try {
168	            Type[] returnTypes = RpcUtils.getReturnTypes(invocation);
169	            Object value;
170	            if (ArrayUtils.isEmpty(returnTypes)) {
171	                // happens when generic invoke or void return
172	                value = in.readObject();
173	            } else if (returnTypes.length == 1) {
174	                value = in.readObject((Class<?>) returnTypes[0]);
175	            } else {
176	                value = in.readObject((Class<?>) returnTypes[0], returnTypes[1]);
177	            }
178	            setValue(value);
179	        } catch (ClassNotFoundException e) {
180	            rethrow(e);
181	        }
182	    }
183	
184	    private void handleException(ObjectInput in) throws IOException {
185	        try {
186	            setException(in.readThrowable());
187	        } catch (ClassNotFoundException e) {
188	            rethrow(e);
189	        }
190	    }
191	
192	    private void handleAttachment(ObjectInput in) throws IOException {
193	        try {
194	            addObjectAttachments(in.readAttachments());
195	        } catch (ClassNotFoundException e) {
196	            rethrow(e);
197	        }
198	    }
199	
200	    private void rethrow(Exception e) throws IOException {
201	        throw new IOException(StringUtils.toString("Read response data failed.", e));
202	    }
203	}
