59	
60	/**
61	 * DubboInvoker
62	 */
63	public class DubboInvoker<T> extends AbstractInvoker<T> {
64	
65	    private final ClientsProvider clientsProvider;
66	
67	    private final AtomicPositiveInteger index = new AtomicPositiveInteger();
68	
69	    private final ReentrantLock destroyLock = new ReentrantLock();
70	
71	    private final Set<Invoker<?>> invokers;
72	
73	    private final int serverShutdownTimeout;
74	
75	    private static final boolean setFutureWhenSync = Boolean.parseBoolean(SystemPropertyConfigUtils.getSystemProperty(
76	            CommonConstants.ThirdPartyProperty.SET_FUTURE_IN_SYNC_MODE, "true"));
77	
78	    public DubboInvoker(Class<T> serviceType, URL url, ClientsProvider clientsProvider) {
79	        this(serviceType, url, clientsProvider, null);
80	    }
81	
82	    public DubboInvoker(Class<T> serviceType, URL url, ClientsProvider clientsProvider, Set<Invoker<?>> invokers) {
83	        super(serviceType, url, new String[] {INTERFACE_KEY, GROUP_KEY, TOKEN_KEY});
84	        this.clientsProvider = clientsProvider;
85	        this.invokers = invokers;
86	        this.serverShutdownTimeout = ConfigurationUtils.getServerShutdownTimeout(getUrl().getScopeModel());
87	    }
88	
89	    @Override
90	    protected Result doInvoke(final Invocation invocation) throws Throwable {
91	        RpcInvocation inv = (RpcInvocation) invocation;
92	        final String methodName = RpcUtils.getMethodName(invocation);
93	        inv.setAttachment(PATH_KEY, getUrl().getPath());
94	        inv.setAttachment(VERSION_KEY, version);
95	
96	        ExchangeClient currentClient;
97	        List<? extends ExchangeClient> exchangeClients = clientsProvider.getClients();
98	        if (exchangeClients.size() == 1) {
99	            currentClient = exchangeClients.get(0);
100	        } else {
101	            currentClient = exchangeClients.get(index.getAndIncrement() % exchangeClients.size());
102	        }
103	        RpcContext.getServiceContext().setLocalAddress(currentClient.getLocalAddress());
104	        try {
105	            boolean isOneway = RpcUtils.isOneway(getUrl(), invocation);
106	
107	            int timeout = RpcUtils.calculateTimeout(getUrl(), invocation, methodName, DEFAULT_TIMEOUT);
108	            if (timeout <= 0) {
109	                return AsyncRpcResult.newDefaultAsyncResult(
110	                        new RpcException(
111	                                RpcException.TIMEOUT_TERMINATE,
112	                                "No time left for making the following call: " + invocation.getServiceName() + "."
113	                                        + RpcUtils.getMethodName(invocation) + ", terminate directly."),
114	                        invocation);
115	            }
116	
117	            invocation.setAttachment(TIMEOUT_KEY, String.valueOf(timeout));
118	
119	            Integer payload = getUrl().getParameter(PAYLOAD, Integer.class);
120	
121	            Request request = new Request();
122	            if (payload != null) {
123	                request.setPayload(payload);
124	            }
125	            request.setData(inv);
126	            request.setVersion(Version.getProtocolVersion());
127	
128	            if (isOneway) {
129	                boolean isSent = getUrl().getMethodParameter(methodName, Constants.SENT_KEY, false);
130	                request.setTwoWay(false);
131	                currentClient.send(request, isSent);
132	                return AsyncRpcResult.newDefaultAsyncResult(invocation);
133	            } else {
134	                request.setTwoWay(true);
135	                ExecutorService executor = getCallbackExecutor(getUrl(), inv);
136	                CompletableFuture<AppResponse> appResponseFuture =
137	                        currentClient.request(request, timeout, executor).thenApply(AppResponse.class::cast);
138	                // save for 2.6.x compatibility, for example, TraceFilter in Zipkin uses com.alibaba.xxx.FutureAdapter
139	                if (setFutureWhenSync || ((RpcInvocation) invocation).getInvokeMode() != InvokeMode.SYNC) {
140	                    FutureContext.getContext().setCompatibleFuture(appResponseFuture);
141	                }
142	                AsyncRpcResult result = new AsyncRpcResult(appResponseFuture, inv);
143	                result.setExecutor(executor);
144	                return result;
145	            }
146	        } catch (TimeoutException e) {
147	            throw new RpcException(
148	                    RpcException.TIMEOUT_EXCEPTION,
149	                    "Invoke remote method timeout. method: " + RpcUtils.getMethodName(invocation) + ", provider: "
150	                            + getUrl() + ", cause: " + e.getMessage(),
151	                    e);
152	        } catch (RemotingException e) {
153	            String remoteExpMsg = "Failed to invoke remote method: " + RpcUtils.getMethodName(invocation)
154	                    + ", provider: " + getUrl() + ", cause: " + e.getMessage();
155	            if (e.getCause() instanceof IOException && e.getCause().getCause() instanceof SerializationException) {
156	                throw new RpcException(RpcException.SERIALIZATION_EXCEPTION, remoteExpMsg, e);
157	            } else {
158	                throw new RpcException(RpcException.NETWORK_EXCEPTION, remoteExpMsg, e);
159	            }
160	        }
161	    }
162	
163	    @Override
164	    public boolean isAvailable() {
165	        if (!super.isAvailable()) {
166	            return false;
167	        }
168	        for (ExchangeClient client : clientsProvider.getClients()) {
169	            if (client.isConnected() && !client.hasAttribute(Constants.CHANNEL_ATTRIBUTE_READONLY_KEY)) {
170	                // cannot write == not Available ?
171	                return true;
172	            }
173	        }
174	        return false;
175	    }
176	
177	    @Override
178	    public void destroy() {
179	        // in order to avoid closing a client multiple times, a counter is used in case of connection per jvm, every
180	        // time when client.close() is called, counter counts down once, and when counter reaches zero, client will be
181	        // closed.
182	        if (!super.isDestroyed()) {
183	            // double check to avoid dup close
184	            destroyLock.lock();
185	            try {
186	                if (super.isDestroyed()) {
187	                    return;
188	                }
189	                super.destroy();
190	                if (invokers != null) {
191	                    invokers.remove(this);
192	                }
193	                clientsProvider.close(ConfigurationUtils.reCalShutdownTime(serverShutdownTimeout));
194	            } finally {
195	                destroyLock.unlock();
196	            }
197	        }
198	    }
199	}
