40	final class ReferenceCountExchangeClient implements ExchangeClient {
41	
42	    private static final ErrorTypeAwareLogger logger =
43	            LoggerFactory.getErrorTypeAwareLogger(ReferenceCountExchangeClient.class);
44	    private final URL url;
45	    private final AtomicInteger referenceCount = new AtomicInteger(0);
46	    private final AtomicInteger disconnectCount = new AtomicInteger(0);
47	    private static final Integer warningPeriod = 50;
48	    private ExchangeClient client;
49	    private int shutdownWaitTime = DEFAULT_SERVER_SHUTDOWN_TIMEOUT;
50	
51	    public ReferenceCountExchangeClient(ExchangeClient client, String codec) {
52	        this.client = client;
53	        this.referenceCount.incrementAndGet();
54	        this.url = client.getUrl();
55	    }
56	
57	    @Override
58	    public void reset(URL url) {
59	        client.reset(url);
