161	    @Override
162	    public void close(int timeout) {
163	        if (referenceCount.decrementAndGet() <= 0) {
164	            if (timeout == 0) {
165	                client.close();
166	
167	            } else {
168	                client.close(timeout);
169	            }
170	
171	            replaceWithLazyClient();
172	        }
173	    }
