182	     * the client will "resurrect".
183	     *
184	     * @return
185	     */
186	    private void replaceWithLazyClient() {
187	        // start warning at second replaceWithLazyClient()
188	        if (disconnectCount.getAndIncrement() % warningPeriod == 1) {
189	            logger.warn(
190	                    PROTOCOL_FAILED_REQUEST,
191	                    "",
192	                    "",
193	                    url.getAddress() + " " + url.getServiceKey()
194	                            + " safe guard client , should not be called ,must have a bug.");
195	        }
196	
197	        // the order of judgment in the if statement cannot be changed.
198	        if (!(client instanceof LazyConnectExchangeClient)) {
199	            client = new LazyConnectExchangeClient(url, client.getExchangeHandler());
200	        }
201	    }
202	
