38	import org.apache.dubbo.rpc.cluster.router.state.BitList;
39	import org.apache.dubbo.rpc.cluster.router.state.TailStateRouter;
40	
41	import static org.apache.dubbo.common.constants.LoggerCodeConstants.CLUSTER_FAILED_RULE_PARSING;
42	
43	/**
44	 * Abstract router which listens to dynamic configuration
45	 */
46	public abstract class AffinityListenableStateRouter<T> extends AbstractStateRouter<T> implements ConfigurationListener {
47	    public static final String NAME = "Affinity_LISTENABLE_ROUTER";
48	    public static final String RULE_SUFFIX = ".affinity-router";
49	
50	    private static final ErrorTypeAwareLogger logger =
51	            LoggerFactory.getErrorTypeAwareLogger(AffinityListenableStateRouter.class);
52	    private volatile AffinityRouterRule affinityRouterRule;
53	    private volatile AffinityStateRouter<T> affinityRouter;
54	    private final String ruleKey;
55	
56	    public AffinityListenableStateRouter(URL url, String ruleKey) {
57	        super(url);
58	        this.setForce(false);
59	        this.init(ruleKey);
60	        this.ruleKey = ruleKey;
61	    }
62	
63	    @Override
64	    public synchronized void process(ConfigChangedEvent event) {
65	        if (logger.isInfoEnabled()) {
66	            logger.info("Notification of affinity rule, change type is: " + event.getChangeType() + ", raw rule is:\n "
67	                    + event.getContent());
68	        }
69	
70	        if (event.getChangeType().equals(ConfigChangeType.DELETED)) {
71	            affinityRouterRule = null;
72	            affinityRouter = null;
73	        } else {
74	            try {
75	                affinityRouterRule = AffinityRuleParser.parse(event.getContent());
76	                generateConditions(affinityRouterRule);
77	            } catch (Exception e) {
78	                logger.error(
79	                        CLUSTER_FAILED_RULE_PARSING,
80	                        "Failed to parse the raw affinity rule",
81	                        "",
82	                        "Failed to parse the raw affinity rule and it will not take effect, please check "
83	                                + "if the affinity rule matches with the template, the raw rule is:\n "
84	                                + event.getContent(),
85	                        e);
86	            }
87	        }
88	    }
89	
90	    @Override
91	    public BitList<Invoker<T>> doRoute(
92	            BitList<Invoker<T>> invokers,
93	            URL url,
94	            Invocation invocation,
95	            boolean needToPrintMessage,
96	            Holder<RouterSnapshotNode<T>> nodeHolder,
97	            Holder<String> messageHolder)
98	            throws RpcException {
99	        if (CollectionUtils.isEmpty(invokers) || affinityRouter == null) {
100	            if (needToPrintMessage) {
101	                messageHolder.set(
102	                        "Directly return. Reason: Invokers from previous router is empty or affinityRouter is null.");
103	            }
104	            return invokers;
105	        }
106	
107	        // We will check enabled status inside each router.
108	        StringBuilder resultMessage = null;
109	        if (needToPrintMessage) {
110	            resultMessage = new StringBuilder();
111	        }
112	        invokers = affinityRouter.route(invokers, url, invocation, needToPrintMessage, nodeHolder);
113	        if (needToPrintMessage) {
114	            resultMessage.append(messageHolder.get());
115	        }
116	
117	        if (needToPrintMessage) {
118	            messageHolder.set(resultMessage.toString());
119	        }
120	
121	        return invokers;
122	    }
123	
124	    @Override
125	    public boolean isForce() {
126	        return (affinityRouterRule != null && affinityRouterRule.isForce());
127	    }
128	
129	    private boolean isRuleRuntime() {
130	        return affinityRouterRule != null && affinityRouterRule.isValid() && affinityRouterRule.isRuntime();
131	    }
132	
133	    private void generateConditions(AbstractRouterRule rule) {
134	        if (rule == null || !rule.isValid()) {
135	            return;
136	        }
137	        AffinityRouterRule affinityRule = (AffinityRouterRule) rule;
138	        affinityRouter = new AffinityStateRouter<>(
139	                getUrl(), affinityRule.getAffinityKey(), affinityRule.getRatio(), affinityRule.isEnabled());
140	        affinityRouter.setNextRouter(TailStateRouter.getInstance());
141	    }
142	
143	    private synchronized void init(String ruleKey) {
144	        if (StringUtils.isEmpty(ruleKey)) {
145	            return;
146	        }
147	        String routerKey = ruleKey + RULE_SUFFIX;
148	        this.getRuleRepository().addListener(routerKey, this);
149	        String rule = this.getRuleRepository().getRule(routerKey, DynamicConfiguration.DEFAULT_GROUP);
150	        if (StringUtils.isNotEmpty(rule)) {
151	            this.process(new ConfigChangedEvent(routerKey, DynamicConfiguration.DEFAULT_GROUP, rule));
152	        }
153	    }
154	
155	    public AffinityStateRouter<T> getAffinityRouter() {
156	        return affinityRouter;
157	    }
158	
159	    @Override
160	    public void stop() {
161	        this.getRuleRepository().removeListener(ruleKey + RULE_SUFFIX, this);
162	    }
163	}
