17	package org.apache.dubbo.rpc.cluster.loadbalance;
18	
19	import org.apache.dubbo.common.URL;
20	import org.apache.dubbo.common.constants.LoadbalanceRules;
21	import org.apache.dubbo.common.utils.StringUtils;
22	import org.apache.dubbo.rpc.AdaptiveMetrics;
23	import org.apache.dubbo.rpc.Constants;
24	import org.apache.dubbo.rpc.Invocation;
25	import org.apache.dubbo.rpc.Invoker;
26	import org.apache.dubbo.rpc.RpcContext;
27	import org.apache.dubbo.rpc.model.ApplicationModel;
28	import org.apache.dubbo.rpc.support.RpcUtils;
29	
30	import java.util.List;
31	import java.util.concurrent.ThreadLocalRandom;
32	
33	import static org.apache.dubbo.common.constants.CommonConstants.DEFAULT_TIMEOUT;
34	import static org.apache.dubbo.common.constants.CommonConstants.LOADBALANCE_KEY;
35	
36	public class AdaptiveLoadBalance extends AbstractLoadBalance {
37	
38	    public static final String NAME = "adaptive";
39	
40	    // default key
41	    private String attachmentKey = "mem,load";
42	
43	    private final AdaptiveMetrics adaptiveMetrics;
44	
45	    public AdaptiveLoadBalance(ApplicationModel scopeModel) {
46	        adaptiveMetrics = scopeModel.getBeanFactory().getBean(AdaptiveMetrics.class);
47	    }
48	
49	    @Override
50	    protected <T> Invoker<T> doSelect(List<Invoker<T>> invokers, URL url, Invocation invocation) {
51	        Invoker<T> invoker = selectByP2C(invokers, invocation);
52	        invocation.setAttachment(Constants.ADAPTIVE_LOADBALANCE_ATTACHMENT_KEY, attachmentKey);
53	        long startTime = System.currentTimeMillis();
54	        invocation.getAttributes().put(Constants.ADAPTIVE_LOADBALANCE_START_TIME, startTime);
55	        invocation.getAttributes().put(LOADBALANCE_KEY, LoadbalanceRules.ADAPTIVE);
56	        adaptiveMetrics.addConsumerReq(getServiceKey(invoker, invocation));
57	        adaptiveMetrics.setPickTime(getServiceKey(invoker, invocation), startTime);
58	
59	        return invoker;
60	    }
61	
62	    private <T> Invoker<T> selectByP2C(List<Invoker<T>> invokers, Invocation invocation) {
63	        int length = invokers.size();
64	        if (length == 1) {
65	            return invokers.get(0);
66	        }
67	
68	        if (length == 2) {
69	            return chooseLowLoadInvoker(invokers.get(0), invokers.get(1), invocation);
70	        }
71	
72	        int pos1 = ThreadLocalRandom.current().nextInt(length);
73	        int pos2 = ThreadLocalRandom.current().nextInt(length - 1);
74	        if (pos2 >= pos1) {
75	            pos2 = pos2 + 1;
76	        }
77	
78	        return chooseLowLoadInvoker(invokers.get(pos1), invokers.get(pos2), invocation);
79	    }
80	
81	    private String getServiceKey(Invoker<?> invoker, Invocation invocation) {
82	
83	        String key = (String) invocation.getAttributes().get(invoker);
84	        if (StringUtils.isNotEmpty(key)) {
85	            return key;
86	        }
87	
88	        key = buildServiceKey(invoker, invocation);
89	        invocation.getAttributes().put(invoker, key);
90	        return key;
91	    }
92	
93	    private String buildServiceKey(Invoker<?> invoker, Invocation invocation) {
94	        URL url = invoker.getUrl();
95	        StringBuilder sb = new StringBuilder(128);
96	        sb.append(url.getAddress()).append(":").append(invocation.getProtocolServiceKey());
97	        return sb.toString();
98	    }
99	
100	    private int getTimeout(Invoker<?> invoker, Invocation invocation) {
101	        URL url = invoker.getUrl();
102	        String methodName = RpcUtils.getMethodName(invocation);
103	        return (int)
104	                RpcUtils.getTimeout(url, methodName, RpcContext.getClientAttachment(), invocation, DEFAULT_TIMEOUT);
105	    }
106	
107	    private <T> Invoker<T> chooseLowLoadInvoker(Invoker<T> invoker1, Invoker<T> invoker2, Invocation invocation) {
108	        int weight1 = getWeight(invoker1, invocation);
109	        int weight2 = getWeight(invoker2, invocation);
110	        int timeout1 = getTimeout(invoker1, invocation);
111	        int timeout2 = getTimeout(invoker2, invocation);
112	        long load1 = Double.doubleToLongBits(
113	                adaptiveMetrics.getLoad(getServiceKey(invoker1, invocation), weight1, timeout1));
114	        long load2 = Double.doubleToLongBits(
115	                adaptiveMetrics.getLoad(getServiceKey(invoker2, invocation), weight2, timeout2));
116	
117	        if (load1 == load2) {
118	            // The sum of weights
119	            int totalWeight = weight1 + weight2;
120	            if (totalWeight > 0) {
121	                int offset = ThreadLocalRandom.current().nextInt(totalWeight);
122	                if (offset < weight1) {
123	                    return invoker1;
124	                }
125	                return invoker2;
126	            }
127	            return ThreadLocalRandom.current().nextInt(2) == 0 ? invoker1 : invoker2;
128	        }
129	        return load1 > load2 ? invoker2 : invoker1;
130	    }
131	}
