17	package org.apache.dubbo.rpc.cluster.loadbalance;
18	
19	import org.apache.dubbo.common.URL;
20	import org.apache.dubbo.common.utils.StringUtils;
21	import org.apache.dubbo.rpc.Invocation;
22	import org.apache.dubbo.rpc.Invoker;
23	import org.apache.dubbo.rpc.cluster.ClusterInvoker;
24	import org.apache.dubbo.rpc.support.RpcUtils;
25	
26	import java.util.Arrays;
27	import java.util.List;
28	import java.util.concurrent.ThreadLocalRandom;
29	
30	import static org.apache.dubbo.common.constants.CommonConstants.TIMESTAMP_KEY;
31	import static org.apache.dubbo.common.constants.RegistryConstants.REGISTRY_SERVICE_REFERENCE_PATH;
32	import static org.apache.dubbo.rpc.cluster.Constants.WEIGHT_KEY;
33	
34	/**
35	 * This class select one provider from multiple providers randomly.
36	 * You can define weights for each provider:
37	 * If the weights are all the same then it will use random.nextInt(number of invokers).
38	 * If the weights are different then it will use random.nextInt(w1 + w2 + ... + wn)
39	 * Note that if the performance of the machine is better than others, you can set a larger weight.
40	 * If the performance is not so good, you can set a smaller weight.
41	 */
42	public class RandomLoadBalance extends AbstractLoadBalance {
43	
44	    public static final String NAME = "random";
45	
46	    /**
47	     * Select one invoker between a list using a random criteria
48	     *
49	     * @param invokers   List of possible invokers
50	     * @param url        URL
51	     * @param invocation Invocation
52	     * @param <T>
53	     * @return The selected invoker
54	     */
55	    @Override
56	    protected <T> Invoker<T> doSelect(List<Invoker<T>> invokers, URL url, Invocation invocation) {
57	        // Number of invokers
58	        int length = invokers.size();
59	
60	        if (!needWeightLoadBalance(invokers, invocation)) {
61	            return invokers.get(ThreadLocalRandom.current().nextInt(length));
62	        }
63	
64	        // Every invoker has the same weight?
65	        boolean sameWeight = true;
66	        // the maxWeight of every invoker, the minWeight = 0 or the maxWeight of the last invoker
67	        int[] weights = new int[length];
68	        // The sum of weights
69	        int totalWeight = 0;
70	        for (int i = 0; i < length; i++) {
71	            int weight = getWeight(invokers.get(i), invocation);
72	            // Sum
73	            totalWeight += weight;
74	            // save for later use
75	            weights[i] = totalWeight;
76	            if (sameWeight && totalWeight != weight * (i + 1)) {
77	                sameWeight = false;
78	            }
79	        }
80	        if (totalWeight > 0 && !sameWeight) {
81	            // If (not every invoker has the same weight & at least one invoker's weight>0), select randomly based on
82	            // totalWeight.
83	            int offset = ThreadLocalRandom.current().nextInt(totalWeight);
84	            // Return an invoker based on the random value.
85	            if (length <= 4) {
86	                for (int i = 0; i < length; i++) {
87	                    if (offset < weights[i]) {
88	                        return invokers.get(i);
89	                    }
90	                }
91	            } else {
92	                int i = Arrays.binarySearch(weights, offset);
93	                if (i < 0) {
94	                    i = -i - 1;
95	                } else {
96	                    while (weights[i + 1] == offset) {
97	                        i++;
98	                    }
99	                    i++;
100	                }
101	                return invokers.get(i);
102	            }
103	        }
104	        // If all invokers have the same weight value or totalWeight=0, return evenly.
105	        return invokers.get(ThreadLocalRandom.current().nextInt(length));
106	    }
107	
108	    private <T> boolean needWeightLoadBalance(List<Invoker<T>> invokers, Invocation invocation) {
109	        Invoker<T> invoker = invokers.get(0);
110	        URL invokerUrl = invoker.getUrl();
111	        if (invoker instanceof ClusterInvoker) {
112	            invokerUrl = ((ClusterInvoker<?>) invoker).getRegistryUrl();
113	        }
114	
115	        // Multiple registry scenario, load balance among multiple registries.
116	        if (REGISTRY_SERVICE_REFERENCE_PATH.equals(invokerUrl.getServiceInterface())) {
117	            String weight = invokerUrl.getParameter(WEIGHT_KEY);
118	            return StringUtils.isNotEmpty(weight);
119	        } else {
120	            String weight = invokerUrl.getMethodParameter(RpcUtils.getMethodName(invocation), WEIGHT_KEY);
121	            if (StringUtils.isNotEmpty(weight)) {
122	                return true;
123	            } else {
124	                String timeStamp = invoker.getUrl().getParameter(TIMESTAMP_KEY);
125	                return StringUtils.isNotEmpty(timeStamp);
126	            }
127	        }
128	    }
129	}
