25	public class BiStreamServerCallListener extends AbstractServerCallListener {
26	
27	    private StreamObserver<Object> requestObserver;
28	
29	    public BiStreamServerCallListener(
30	            RpcInvocation invocation, Invoker<?> invoker, FlowControlStreamObserver<Object> responseObserver) {
31	        super(invocation, invoker, responseObserver);
32	        invocation.setArguments(new Object[] {responseObserver});
33	        invoke();
34	    }
35	
36	    @Override
37	    @SuppressWarnings("unchecked")
38	    public void onReturn(Object value) {
39	        requestObserver = (StreamObserver<Object>) value;
40	    }
41	
42	    @Override
43	    public void onMessage(Object message) {
44	        if (message instanceof Object[]) {
45	            message = ((Object[]) message)[0];
46	        }
47	        requestObserver.onNext(message);
48	        if (((FlowControlStreamObserver<Object>) responseObserver).isAutoRequestN()) {
49	            ((FlowControlStreamObserver<Object>) responseObserver).request(1);
50	        }
51	    }
52	
53	    @Override
54	    public void onCancel(long code) {
55	        requestObserver.onError(new HttpStatusException((int) code));
56	    }
57	
58	    @Override
59	    public void onComplete() {
60	        requestObserver.onCompleted();
61	    }
62	}
