37	        }
38	    }
39	
40	    @Override
41	    public void onMessage(Object message) {
42	        Class<?>[] params = invocation.getParameterTypes();
43	        if (params.length == 1) {
44	            if (params[0].isInstance(responseObserver)) {
45	                invocation.setArguments(new Object[] {responseObserver});
46	                return;
47	            }
48	        }
49	        if (message instanceof Object[]) {
50	            message = ((Object[]) message)[0];
51	        }
52	        invocation.setArguments(new Object[] {message, responseObserver});
53	    }
54	
55	    @Override
56	    public void onCancel(long code) {
57	        responseObserver.onError(new HttpStatusException((int) code));
58	    }
59	
60	    @Override
61	    public void onComplete() {
62	        invoke();
63	    }
64	}
