48	
49	public class GrpcHttp2ServerTransportListener extends GenericHttp2ServerTransportListener
50	        implements Http2TransportListener {
51	
52	    private static final ErrorTypeAwareLogger LOGGER =
53	            LoggerFactory.getErrorTypeAwareLogger(GrpcHttp2ServerTransportListener.class);
54	
55	    public GrpcHttp2ServerTransportListener(H2StreamChannel h2StreamChannel, URL url, FrameworkModel frameworkModel) {
56	        super(h2StreamChannel, url, frameworkModel);
57	    }
58	
59	    @Override
60	    protected void onBeforeMetadata(Http2Header metadata) {}
61	
62	    @Override
63	    protected Executor initializeExecutor(URL url, Http2Header metadata) {
64	        return getExecutor(url, metadata);
65	    }
66	
67	    @Override
68	    protected void onPrepareMetadata(Http2Header metadata) {
69	        doRoute(metadata);
70	    }
71	
72	    @Override
73	    protected void onMetadataCompletion(Http2Header metadata) {
74	        processGrpcHeaders(metadata);
75	        super.onMetadataCompletion(metadata);
76	    }
77	
78	    private void processGrpcHeaders(Http2Header metadata) {
79	        String messageEncoding = metadata.header(GrpcHeaderNames.GRPC_ENCODING.getName());
80	        if (messageEncoding != null && !Identity.MESSAGE_ENCODING.equals(messageEncoding)) {
81	            DeCompressor compressor = DeCompressor.getCompressor(getFrameworkModel(), messageEncoding);
82	            if (compressor == null) {
83	                throw new UnimplementedException(
84	                        GrpcHeaderNames.GRPC_ENCODING.getName() + " '" + messageEncoding + "'");
85	            }
86	            ((GrpcStreamingDecoder) getStreamingDecoder()).setDeCompressor(compressor);
87	        }
88	    }
89	
90	    @Override
91	    protected StreamingDecoder newStreamingDecoder() {
92	        return new GrpcStreamingDecoder();
93	    }
94	
95	    @Override
96	    protected Http2ServerChannelObserver newResponseObserver(H2StreamChannel h2StreamChannel) {
97	        return new GrpcUnaryServerChannelObserver(getFrameworkModel(), h2StreamChannel);
98	    }
99	
100	    @Override
101	    protected Http2ServerChannelObserver newStreamResponseObserver(H2StreamChannel h2StreamChannel) {
102	        return new GrpcStreamServerChannelObserver(getFrameworkModel(), h2StreamChannel);
103	    }
104	
105	    @Override
106	    protected Http2ServerChannelObserver prepareResponseObserver(Http2ServerChannelObserver responseObserver) {
107	        responseObserver.addTrailersCustomizer(getExceptionCustomizerWrapper()::customizeGrpcStatus);
108	        return super.prepareResponseObserver(responseObserver);
109	    }
110	
111	    @Override
112	    protected HttpMessageListener buildHttpMessageListener() {
113	        return getContext().isHasStub() ? super.buildHttpMessageListener() : new LazyFindMethodListener();
114	    }
115	
116	    @Override
117	    protected void prepareUnaryServerCall() {
118	        if (needWrap()) {
119	            getExceptionCustomizerWrapper().setNeedWrap(true);
120	        }
121	    }
122	
123	    private boolean needWrap() {
124	        RpcInvocationBuildContext context = getContext();
125	        if (context.isHasStub()) {
126	            return false;
127	        }
128	        MethodMetadata methodMetadata = context.getMethodMetadata();
129	        return ReflectionPackableMethod.needWrap(
130	                context.getMethodDescriptor(),
131	                methodMetadata.getActualRequestTypes(),
132	                methodMetadata.getActualResponseType());
133	    }
134	
135	    @Override
136	    protected RpcInvocation onBuildRpcInvocationCompletion(RpcInvocation invocation) {
137	        String timeoutString = getHttpMetadata().header(GrpcHeaderNames.GRPC_TIMEOUT.getName());
138	        try {
139	            if (timeoutString != null) {
140	                Long timeout = GrpcUtils.parseTimeoutToMills(timeoutString);
141	                invocation.put(CommonConstants.TIMEOUT_KEY, timeout);
142	            }
143	        } catch (Throwable t) {
144	            LOGGER.warn(
145	                    PROTOCOL_FAILED_PARSE,
146	                    "",
147	                    "",
148	                    String.format(
149	                            "Failed to parse request timeout set from:%s, service=%s " + "method=%s",
150	                            timeoutString,
151	                            getContext().getServiceDescriptor().getInterfaceName(),
152	                            getContext().getMethodName()));
153	        }
154	        return invocation;
155	    }
156	
157	    @Override
158	    protected Function<Throwable, Object> getExceptionCustomizer() {
159	        return getExceptionCustomizerWrapper()::customizeGrpc;
160	    }
161	
162	    @Override
163	    protected void setMethodDescriptor(MethodDescriptor methodDescriptor) {
164	        ((GrpcCompositeCodec) getContext().getHttpMessageDecoder()).loadPackableMethod(methodDescriptor);
165	        super.setMethodDescriptor(methodDescriptor);
166	    }
167	
168	    private class LazyFindMethodListener implements HttpMessageListener {
169	
170	        private final StreamingDecoder streamingDecoder;
171	
172	        private LazyFindMethodListener() {
173	            streamingDecoder = getStreamingDecoder();
174	            streamingDecoder.setFragmentListener(new DetermineMethodDescriptorListener());
175	        }
176	
177	        @Override
178	        public void onMessage(InputStream inputStream) {
179	            streamingDecoder.decode(inputStream);
180	        }
181	    }
182	
183	    private class DetermineMethodDescriptorListener implements StreamingDecoder.FragmentListener {
184	
185	        @Override
186	        public void bytesRead(int numBytes) {
187	            // Delegate to the H2StreamChannel for flow control
188	            try {
189	                getH2StreamChannel().consumeBytes(numBytes);
190	            } catch (Exception e) {
191	                LOGGER.warn(PROTOCOL_FAILED_PARSE, "", "", "Failed to consume bytes for flow control", e);
192	            }
193	        }
194	
195	        @Override
196	        public void onClose() {
197	            // no op
198	        }
199	
200	        @Override
201	        public void onFragmentMessage(InputStream rawMessage, int messageLength) {
202	            try {
203	                RpcInvocationBuildContext context = getContext();
204	                if (context.getMethodDescriptor() == null) {
205	                    MethodDescriptor methodDescriptor = DescriptorUtils.findTripleMethodDescriptor(
206	                            context.getServiceDescriptor(), context.getMethodName(), rawMessage);
207	                    setMethodDescriptor(methodDescriptor);
208	                    setHttpMessageListener(GrpcHttp2ServerTransportListener.super.buildHttpMessageListener());
209	                }
210	
211	                ((GrpcStreamingDecoder) getStreamingDecoder()).invokeListener(rawMessage, messageLength);
212	            } catch (IOException e) {
213	                throw new DecodeException(e);
214	            }
215	        }
216	    }
217	}
