41	/**
42	 * Config center implementation of {@link MetricsCollector}
43	 */
44	@Activate
45	public class ConfigCenterMetricsCollector extends CombMetricsCollector<ConfigCenterEvent> {
46	
47	    private Boolean collectEnabled = null;
48	    private final ApplicationModel applicationModel;
49	    private final AtomicBoolean samplesChanged = new AtomicBoolean(true);
50	
51	    private final ConcurrentHashMap<ConfigCenterMetric, AtomicLong> updatedMetrics = new ConcurrentHashMap<>();
52	
53	    public ConfigCenterMetricsCollector(ApplicationModel applicationModel) {
54	        super(null);
55	        this.applicationModel = applicationModel;
56	        super.setEventMulticaster(new ConfigCenterSubDispatcher(this));
57	    }
58	
59	    public void setCollectEnabled(Boolean collectEnabled) {
60	        if (collectEnabled != null) {
61	            this.collectEnabled = collectEnabled;
62	        }
63	    }
64	
65	    @Override
66	    public boolean isCollectEnabled() {
67	        if (collectEnabled == null) {
68	            ConfigManager configManager = applicationModel.getApplicationConfigManager();
69	            configManager.getMetrics().ifPresent(metricsConfig -> setCollectEnabled(metricsConfig.getEnableMetadata()));
70	        }
71	        return Optional.ofNullable(collectEnabled).orElse(false);
72	    }
73	
74	    public void increase(String key, String group, String protocol, String changeTypeName, int size) {
75	        if (!isCollectEnabled()) {
76	            return;
77	        }
78	        ConfigCenterMetric metric =
79	                new ConfigCenterMetric(applicationModel.getApplicationName(), key, group, protocol, changeTypeName);
80	        AtomicLong metrics = updatedMetrics.get(metric);
81	        if (metrics == null) {
82	            metrics = ConcurrentHashMapUtils.computeIfAbsent(updatedMetrics, metric, k -> new AtomicLong(0L));
83	            samplesChanged.set(true);
84	        }
85	        metrics.addAndGet(size);
86	    }
87	
88	    @Override
89	    public List<MetricSample> collect() {
90	        // Add metrics to reporter
91	        List<MetricSample> list = new ArrayList<>();
92	        if (!isCollectEnabled()) {
93	            return list;
94	        }
95	        updatedMetrics.forEach((k, v) -> list.add(new GaugeMetricSample<>(
96	                MetricsKey.CONFIGCENTER_METRIC_TOTAL, k.getTags(), CONFIGCENTER, v, AtomicLong::get)));
97	        return list;
98	    }
99	
100	    @Override
101	    public boolean calSamplesChanged() {
102	        // CAS to get and reset the flag in an atomic operation
103	        return samplesChanged.compareAndSet(true, false);
104	    }
105	}
