43	import static org.apache.dubbo.common.constants.LoggerCodeConstants.PROTOCOL_FAILED_RESPONSE;
44	
45	public final class Http2TripleClientStream extends AbstractTripleClientStream {
46	
47	    private static final ErrorTypeAwareLogger LOGGER =
48	            LoggerFactory.getErrorTypeAwareLogger(Http2TripleClientStream.class);
49	
50	    private final Channel parent;
51	
52	    public Http2TripleClientStream(
53	            FrameworkModel frameworkModel,
54	            Executor executor,
55	            Channel parent,
56	            ClientStream.Listener listener,
57	            TripleWriteQueue writeQueue) {
58	        super(frameworkModel, executor, writeQueue, listener, parent);
59	        this.parent = parent;
60	    }
61	
62	    /**
63	     * For test only
64	     */
65	    public Http2TripleClientStream(
66	            FrameworkModel frameworkModel,
67	            Executor executor,
68	            TripleWriteQueue writeQueue,
69	            ClientStream.Listener listener,
70	            Http2StreamChannel http2StreamChannel) {
71	        super(frameworkModel, executor, writeQueue, listener, http2StreamChannel);
72	        this.parent = http2StreamChannel.parent();
73	    }
74	
75	    @Override
76	    protected TripleStreamChannelFuture initStreamChannel0(Channel parent) {
77	        Http2StreamChannelBootstrap bootstrap = new Http2StreamChannelBootstrap(parent);
78	        // Disable Netty's automatic stream flow control to enable manual flow control
79	        bootstrap.option(Http2StreamChannelOption.AUTO_STREAM_FLOW_CONTROL, false);
80	        bootstrap.handler(new ChannelInboundHandlerAdapter() {
81	            @Override
82	            public void handlerAdded(ChannelHandlerContext ctx) {
83	                ctx.channel()
84	                        .pipeline()
85	                        .addLast(new TripleCommandOutBoundHandler())
86	                        .addLast(new TripleHttp2ClientResponseHandler(createTransportListener()));
87	            }
88	        });
89	        TripleStreamChannelFuture streamChannelFuture = new TripleStreamChannelFuture(parent);
90	        writeQueue.enqueue(CreateStreamQueueCommand.create(bootstrap, streamChannelFuture));
91	        return streamChannelFuture;
92	    }
93	
94	    @Override
95	    protected void consumeBytes(int numBytes) {
96	        if (numBytes <= 0) {
97	            return;
98	        }
99	
100	        // todo The current implementation is not optimal, and alternative implementations should be considered.
101	
102	        Channel streamChannel = getStreamChannelFuture().getNow();
103	        if (!(streamChannel instanceof Http2StreamChannel)) {
104	            return;
105	        }
106	
107	        Http2StreamChannel http2StreamChannel = (Http2StreamChannel) streamChannel;
108	
109	        // Get Http2Connection from parent channel pipeline
110	        Http2Connection http2Connection = getHttp2Connection();
111	        if (http2Connection == null) {
112	            LOGGER.debug("Http2Connection not available for flow control");
113	            return;
114	        }
115	
116	        Http2LocalFlowController localFlowController = http2Connection.local().flowController();
117	        int streamId = http2StreamChannel.stream().id();
118	        Http2Stream stream = http2Connection.stream(streamId);
119	        if (stream == null) {
120	            LOGGER.debug("Stream {} not found in connection, skip consumeBytes", streamId);
121	            return;
122	        }
123	
124	        // Consume bytes to trigger WINDOW_UPDATE frame
125	        // This must be executed in the event loop thread
126	        if (http2StreamChannel.eventLoop().inEventLoop()) {
127	            try {
128	                localFlowController.consumeBytes(stream, numBytes);
129	            } catch (Exception e) {
130	                LOGGER.warn(PROTOCOL_FAILED_RESPONSE, "", "", "Failed to consumeBytes for stream " + streamId, e);
131	            }
132	        } else {
133	            http2StreamChannel.eventLoop().execute(() -> {
134	                try {
135	                    localFlowController.consumeBytes(stream, numBytes);
136	                } catch (Exception e) {
137	                    LOGGER.warn(PROTOCOL_FAILED_RESPONSE, "", "", "Failed to consumeBytes for stream " + streamId, e);
138	                }
139	            });
140	        }
141	    }
142	
143	    /**
144	     * Get Http2Connection from parent channel pipeline.
145	     */
146	    private Http2Connection getHttp2Connection() {
147	        if (parent == null) {
148	            return null;
149	        }
150	        ChannelHandlerContext ctx = parent.pipeline().context(Http2FrameCodec.class);
151	        if (ctx == null) {
152	            return null;
153	        }
154	        Http2FrameCodec codec = (Http2FrameCodec) ctx.handler();
155	        return codec.connection();
156	    }
157	}
