31	
32	public class Http2UnaryServerChannelObserver extends Http2StreamServerChannelObserver {
33	
34	    private static final FluentLogger LOGGER = FluentLogger.of(Http2UnaryServerChannelObserver.class);
35	
36	    public Http2UnaryServerChannelObserver(FrameworkModel frameworkModel, H2StreamChannel h2StreamChannel) {
37	        super(frameworkModel, h2StreamChannel);
38	    }
39	
40	    @Override
41	    protected void doOnNext(Object data) throws Throwable {
42	        int statusCode = resolveStatusCode(data);
43	        HttpOutputMessage message = buildMessage(statusCode, data);
44	        HttpMetadata metadata = buildMetadata(statusCode, data, null, message);
45	        customizeTrailers(metadata.headers(), null);
46	        sendMetadata(metadata);
47	        sendMessage(message);
48	    }
49	
50	    @Override
51	    protected void doOnError(Throwable throwable) throws Throwable {
52	        int statusCode = resolveErrorStatusCode(throwable);
53	        Object data = buildErrorResponse(statusCode, throwable);
54	        HttpOutputMessage message;
55	        try {
56	            message = buildMessage(statusCode, data);
57	        } catch (Throwable t) {
58	            LOGGER.internalError("Failed to build message", t);
59	            message = encodeHttpOutputMessage(data);
60	        }
61	        HttpMetadata metadata = buildMetadata(statusCode, data, throwable, message);
62	        customizeTrailers(metadata.headers(), throwable);
63	        sendMetadata(metadata);
64	        sendMessage(message);
65	    }
66	
67	    @Override
68	    protected void customizeTrailers(HttpHeaders headers, Throwable throwable) {
69	        StreamUtils.putHeaders(headers, getResponseAttachments(), TripleProtocol.CONVERT_NO_LOWER_HEADER);
70	        super.customizeTrailers(headers, throwable);
71	    }
72	
73	    @Override
74	    protected void doOnCompleted(Throwable throwable) {}
75	
76	    @Override
77	    protected HttpOutputMessage encodeHttpOutputMessage(Object data) {
78	        return getHttpChannel().newOutputMessage(true);
79	    }
80	
81	    @Override
82	    protected HttpMetadata encodeHttpMetadata(boolean endStream) {
83	        return new Http2MetadataFrame(new NettyHttpHeaders<>(new DefaultHttp2Headers(false, 8)), endStream);
84	    }
85	}
