17	package org.apache.dubbo.rpc.protocol.tri.h12.http1;
18	
19	import org.apache.dubbo.remoting.http12.HttpChannel;
20	import org.apache.dubbo.remoting.http12.HttpHeaderNames;
21	import org.apache.dubbo.remoting.http12.HttpHeaders;
22	import org.apache.dubbo.remoting.http12.HttpOutputMessage;
23	import org.apache.dubbo.remoting.http12.h1.Http1ServerChannelObserver;
24	import org.apache.dubbo.rpc.protocol.tri.ExceptionUtils;
25	import org.apache.dubbo.rpc.protocol.tri.TripleProtocol;
26	
27	import java.io.ByteArrayOutputStream;
28	import java.io.OutputStream;
29	
30	import io.netty.buffer.ByteBufOutputStream;
31	
32	public final class Http1UnaryServerChannelObserver extends Http1ServerChannelObserver {
33	
34	    public Http1UnaryServerChannelObserver(HttpChannel httpChannel) {
35	        super(httpChannel);
36	    }
37	
38	    @Override
39	    protected void doOnNext(Object data) throws Throwable {
40	        int statusCode = resolveStatusCode(data);
41	        HttpOutputMessage message = buildMessage(statusCode, data);
42	        sendMetadata(buildMetadata(statusCode, data, null, message));
43	        sendMessage(message);
44	    }
45	
46	    @Override
47	    protected void doOnError(Throwable throwable) throws Throwable {
48	        int statusCode = resolveErrorStatusCode(throwable);
49	        Object data = buildErrorResponse(statusCode, throwable);
50	        HttpOutputMessage message = buildMessage(statusCode, data);
51	        sendMetadata(buildMetadata(statusCode, data, throwable, message));
52	        sendMessage(message);
53	    }
54	
55	    @Override
56	    protected void customizeHeaders(HttpHeaders headers, Throwable throwable, HttpOutputMessage message) {
57	        super.customizeHeaders(headers, throwable, message);
58	        int contentLength = 0;
59	        if (message != null) {
60	            OutputStream body = message.getBody();
61	            if (body instanceof ByteBufOutputStream) {
62	                contentLength = ((ByteBufOutputStream) body).writtenBytes();
63	            } else if (body instanceof ByteArrayOutputStream) {
64	                contentLength = ((ByteArrayOutputStream) body).size();
65	            } else {
66	                throw new IllegalArgumentException("Unsupported body type: " + body.getClass());
67	            }
68	        }
69	        headers.set(HttpHeaderNames.CONTENT_LENGTH.getKey(), String.valueOf(contentLength));
70	    }
71	
72	    @Override
73	    protected Throwable customizeError(Throwable throwable) {
74	        throwable = super.customizeError(throwable);
75	        if (throwable == null) {
76	            doOnCompleted(null);
77	        }
78	        return throwable;
79	    }
80	
81	    @Override
82	    protected String getDisplayMessage(Throwable throwable) {
83	        return TripleProtocol.VERBOSE_ENABLED
84	                ? ExceptionUtils.buildVerboseMessage(throwable)
85	                : super.getDisplayMessage(throwable);
86	    }
87	}
