50	    public String getValue(Map<String, String> sample, URL url, Invocation invocation) {
51	        try {
52	            // split the rule
53	            String[] expressArray = key.split("\\.");
54	            String argumentExpress = expressArray[0];
55	            final Matcher matcher = ARGUMENTS_PATTERN.matcher(argumentExpress);
56	            if (!matcher.find()) {
57	                return DOES_NOT_FOUND_VALUE;
58	            }
59	
60	            // extract the argument index
61	            int index = Integer.parseInt(matcher.group(1));
62	            if (index < 0 || index > invocation.getArguments().length) {
63	                return DOES_NOT_FOUND_VALUE;
64	            }
65	
66	            // extract the argument value
67	            return String.valueOf(invocation.getArguments()[index]);
68	        } catch (Exception e) {
69	            logger.warn(
70	                    CLUSTER_FAILED_EXEC_CONDITION_ROUTER,
71	                    "Parse argument match condition failed",
72	                    "",
73	                    "Invalid , will ignore., ",
74	                    e);
75	        }
76	        return DOES_NOT_FOUND_VALUE;
77	    }
78	}
