34	/**
35	 * analysis the arguments in the rule.
36	 * Examples would be like this:
37	 * "attachments[foo]=bar", whenCondition is that the attachment value of 'foo' is equal to 'bar'.
38	 */
39	@Activate
40	public class AttachmentConditionMatcher extends AbstractConditionMatcher {
41	    private static final ErrorTypeAwareLogger logger =
42	            LoggerFactory.getErrorTypeAwareLogger(AttachmentConditionMatcher.class);
43	    private static final Pattern ATTACHMENTS_PATTERN = Pattern.compile("attachments\\[(.+)\\]");
44	
45	    public AttachmentConditionMatcher(String key, ModuleModel model) {
46	        super(key, model);
47	    }
48	
49	    @Override
50	    protected String getValue(Map<String, String> sample, URL url, Invocation invocation) {
51	        try {
52	            // split the rule
53	            String[] expressArray = key.split("\\.");
54	            String argumentExpress = expressArray[0];
55	            final Matcher matcher = ATTACHMENTS_PATTERN.matcher(argumentExpress);
56	            if (!matcher.find()) {
57	                return DOES_NOT_FOUND_VALUE;
58	            }
59	
60	            // extract the argument index
61	            String attachmentKey = matcher.group(1);
62	            if (StringUtils.isEmpty(attachmentKey)) {
63	                return DOES_NOT_FOUND_VALUE;
64	            }
65	
66	            // extract the argument value
67	            return invocation.getAttachment(attachmentKey);
68	        } catch (Exception e) {
69	            logger.warn(
70	                    CLUSTER_FAILED_EXEC_CONDITION_ROUTER,
71	                    "condition state router attachment match failed",
72	                    "",
73	                    "Invalid match condition: " + key,
74	                    e);
75	        }
76	        return DOES_NOT_FOUND_VALUE;
77	    }
78	}
