28	import java.util.List;
29	import java.util.Map;
30	import java.util.Set;
31	
32	import static org.apache.dubbo.common.constants.CommonConstants.METHODS_KEY;
33	import static org.apache.dubbo.common.constants.CommonConstants.METHOD_KEY;
34	import static org.apache.dubbo.common.constants.LoggerCodeConstants.CLUSTER_FAILED_EXEC_CONDITION_ROUTER;
35	
36	/**
37	 * The abstract implementation of ConditionMatcher, records the match and mismatch patterns of this matcher while at the same time
38	 * provides the common match logics.
39	 */
40	public abstract class AbstractConditionMatcher implements ConditionMatcher {
41	    public static final ErrorTypeAwareLogger logger =
42	            LoggerFactory.getErrorTypeAwareLogger(AbstractConditionMatcher.class);
43	    public static final String DOES_NOT_FOUND_VALUE = "dubbo_internal_not_found_argument_condition_value";
44	    final Set<String> matches = new HashSet<>();
45	    final Set<String> mismatches = new HashSet<>();
46	    private final ModuleModel model;
47	    private final List<ValuePattern> valueMatchers;
48	    protected final String key;
49	
50	    public AbstractConditionMatcher(String key, ModuleModel model) {
51	        this.key = key;
52	        this.model = model;
53	        this.valueMatchers = model.getExtensionLoader(ValuePattern.class).getActivateExtensions();
54	    }
55	
56	    public static String getSampleValueFromUrl(
57	            String conditionKey, Map<String, String> sample, URL param, Invocation invocation) {
58	        String sampleValue;
59	        // get real invoked method name from invocation
60	        if (invocation != null && (METHOD_KEY.equals(conditionKey) || METHODS_KEY.equals(conditionKey))) {
61	            sampleValue = RpcUtils.getMethodName(invocation);
62	        } else {
63	            sampleValue = sample.get(conditionKey);
64	        }
65	
66	        return sampleValue;
67	    }
68	
69	    public boolean isMatch(Map<String, String> sample, URL param, Invocation invocation, boolean isWhenCondition) {
70	        String value = getValue(sample, param, invocation);
71	        if (value == null) {
72	            // if key does not present in whichever of url, invocation or attachment based on the matcher type, then
73	            // return false.
74	            return false;
75	        }
76	
77	        if (!matches.isEmpty() && mismatches.isEmpty()) {
78	            for (String match : matches) {
79	                if (doPatternMatch(match, value, param, invocation, isWhenCondition)) {
80	                    return true;
81	                }
82	            }
83	            return false;
84	        }
85	
86	        if (!mismatches.isEmpty() && matches.isEmpty()) {
87	            for (String mismatch : mismatches) {
88	                if (doPatternMatch(mismatch, value, param, invocation, isWhenCondition)) {
89	                    return false;
90	                }
91	            }
92	            return true;
93	        }
94	
95	        if (!matches.isEmpty() && !mismatches.isEmpty()) {
96	            // when both mismatches and matches contain the same value, then using mismatches first
97	            for (String mismatch : mismatches) {
98	                if (doPatternMatch(mismatch, value, param, invocation, isWhenCondition)) {
99	                    return false;
100	                }
101	            }
102	            for (String match : matches) {
103	                if (doPatternMatch(match, value, param, invocation, isWhenCondition)) {
104	                    return true;
105	                }
106	            }
107	            return false;
108	        }
109	        return false;
110	    }
111	
112	    @Override
113	    public Set<String> getMatches() {
114	        return matches;
115	    }
116	
117	    @Override
118	    public Set<String> getMismatches() {
119	        return mismatches;
120	    }
121	
122	    // range, equal or other methods
123	    protected boolean doPatternMatch(
124	            String pattern, String value, URL url, Invocation invocation, boolean isWhenCondition) {
125	        for (ValuePattern valueMatcher : valueMatchers) {
126	            if (valueMatcher.shouldMatch(pattern)) {
127	                return valueMatcher.match(pattern, value, url, invocation, isWhenCondition);
128	            }
129	        }
130	        // this should never happen.
131	        logger.error(
132	                CLUSTER_FAILED_EXEC_CONDITION_ROUTER,
133	                "Executing condition rule value match expression error.",
134	                "pattern is " + pattern + ", value is " + value + ", condition type "
135	                        + (isWhenCondition ? "when" : "then"),
136	                "There should at least has one ValueMatcher instance that applies to all patterns, will force to use wildcard matcher now.");
137	
138	        ValuePattern paramValueMatcher =
139	                model.getExtensionLoader(ValuePattern.class).getExtension("wildcard");
140	        return paramValueMatcher.match(pattern, value, url, invocation, isWhenCondition);
141	    }
142	
143	    /**
144	     * Used to get value from different places of the request context, for example, url, attachment and invocation.
145	     * This makes condition rule possible to check values in any place of a request.
146	     */
147	    protected abstract String getValue(Map<String, String> sample, URL url, Invocation invocation);
148	}
