49	/**
50	 * Abstract router which listens to dynamic configuration
51	 */
52	public abstract class ListenableStateRouter<T> extends AbstractStateRouter<T> implements ConfigurationListener {
53	    public static final String NAME = "LISTENABLE_ROUTER";
54	    public static final String RULE_SUFFIX = ".condition-router";
55	
56	    private static final ErrorTypeAwareLogger logger =
57	            LoggerFactory.getErrorTypeAwareLogger(ListenableStateRouter.class);
58	    private volatile AbstractRouterRule routerRule;
59	    private volatile List<ConditionStateRouter<T>> conditionRouters = Collections.emptyList();
60	
61	    // for v3.1
62	    private volatile List<MultiDestConditionRouter<T>> multiDestConditionRouters = Collections.emptyList();
63	    private final String ruleKey;
64	
65	    public ListenableStateRouter(URL url, String ruleKey) {
66	        super(url);
67	        this.setForce(false);
68	        this.init(ruleKey);
69	        this.ruleKey = ruleKey;
70	    }
71	
72	    @Override
73	    public synchronized void process(ConfigChangedEvent event) {
74	        if (logger.isInfoEnabled()) {
75	            logger.info("Notification of condition rule, change type is: " + event.getChangeType() + ", raw rule is:\n "
76	                    + event.getContent());
77	        }
78	
79	        if (event.getChangeType().equals(ConfigChangeType.DELETED)) {
80	            routerRule = null;
81	            conditionRouters = Collections.emptyList();
82	            // for v3.1
83	            multiDestConditionRouters = Collections.emptyList();
84	        } else {
85	            try {
86	                routerRule = ConditionRuleParser.parse(event.getContent());
87	                generateConditions(routerRule);
88	            } catch (Exception e) {
89	                logger.error(
90	                        CLUSTER_FAILED_RULE_PARSING,
91	                        "Failed to parse the raw condition rule",
92	                        "",
93	                        "Failed to parse the raw condition rule and it will not take effect, please check "
94	                                + "if the condition rule matches with the template, the raw rule is:\n "
95	                                + event.getContent(),
96	                        e);
97	            }
98	        }
99	    }
100	
101	    @Override
102	    public BitList<Invoker<T>> doRoute(
103	            BitList<Invoker<T>> invokers,
104	            URL url,
105	            Invocation invocation,
106	            boolean needToPrintMessage,
107	            Holder<RouterSnapshotNode<T>> nodeHolder,
108	            Holder<String> messageHolder)
109	            throws RpcException {
110	        if (CollectionUtils.isEmpty(invokers)
111	                || (conditionRouters.size() == 0 && multiDestConditionRouters.size() == 0)) {
112	            if (needToPrintMessage) {
113	                messageHolder.set(
114	                        "Directly return. Reason: Invokers from previous router is empty or conditionRouters is empty.");
115	            }
116	            return invokers;
117	        }
118	
119	        // We will check enabled status inside each router.
120	        StringBuilder resultMessage = null;
121	        if (needToPrintMessage) {
122	            resultMessage = new StringBuilder();
123	        }
124	
125	        List<? extends AbstractStateRouter<T>> routers;
126	        if (routerRule instanceof MultiDestConditionRouterRule) {
127	            routers = multiDestConditionRouters;
128	        } else {
129	            routers = conditionRouters;
130	        }
131	
132	        for (AbstractStateRouter<T> router : routers) {
133	            invokers = router.route(invokers, url, invocation, needToPrintMessage, nodeHolder);
134	            if (needToPrintMessage) {
135	                resultMessage.append(messageHolder.get());
136	            }
137	        }
138	
139	        if (needToPrintMessage) {
140	            messageHolder.set(resultMessage.toString());
141	        }
142	
143	        return invokers;
144	    }
145	
146	    @Override
147	    public boolean isForce() {
148	        return (routerRule != null && routerRule.isForce());
149	    }
150	
151	    private boolean isRuleRuntime() {
152	        return routerRule != null && routerRule.isValid() && routerRule.isRuntime();
153	    }
154	
155	    private void generateConditions(AbstractRouterRule rule) {
156	        if (rule == null || !rule.isValid()) {
157	            return;
158	        }
159	
160	        if (rule instanceof ConditionRouterRule) {
161	            this.conditionRouters = ((ConditionRouterRule) rule)
162	                    .getConditions().stream()
163	                            .map(condition ->
164	                                    new ConditionStateRouter<T>(getUrl(), condition, rule.isForce(), rule.isEnabled()))
165	                            .collect(Collectors.toList());
166	
167	            for (ConditionStateRouter<T> conditionRouter : this.conditionRouters) {
168	                conditionRouter.setNextRouter(TailStateRouter.getInstance());
169	            }
170	        } else if (rule instanceof MultiDestConditionRouterRule) {
171	            this.multiDestConditionRouters = ((MultiDestConditionRouterRule) rule)
172	                    .getConditions().stream()
173	                            .map(condition -> new MultiDestConditionRouter<T>(
174	                                    getUrl(), condition, rule.isForce(), rule.isEnabled()))
175	                            .collect(Collectors.toList());
176	
177	            for (MultiDestConditionRouter<T> conditionRouter : this.multiDestConditionRouters) {
178	                conditionRouter.setNextRouter(TailStateRouter.getInstance());
179	            }
180	        }
181	    }
182	
183	    private synchronized void init(String ruleKey) {
184	        if (StringUtils.isEmpty(ruleKey)) {
185	            return;
186	        }
187	        String routerKey = ruleKey + RULE_SUFFIX;
188	        this.getRuleRepository().addListener(routerKey, this);
189	        String rule = this.getRuleRepository().getRule(routerKey, DynamicConfiguration.DEFAULT_GROUP);
190	        if (StringUtils.isNotEmpty(rule)) {
191	            this.process(new ConfigChangedEvent(routerKey, DynamicConfiguration.DEFAULT_GROUP, rule));
192	        }
193	    }
194	
195	    @Override
196	    public void stop() {
197	        this.getRuleRepository().removeListener(ruleKey + RULE_SUFFIX, this);
198	    }
199	}
