37	public abstract class AbstractLoadBalance implements LoadBalance {
38	    /**
39	     * Calculate the weight according to the uptime proportion of warmup time
40	     * the new weight will be within 1(inclusive) to weight(inclusive)
41	     *
42	     * @param uptime the uptime in milliseconds
43	     * @param warmup the warmup time in milliseconds
44	     * @param weight the weight of an invoker
45	     * @return weight which takes warmup into account
46	     */
47	    static int calculateWarmupWeight(int uptime, int warmup, int weight) {
48	        int ww = (int) (uptime / ((float) warmup / weight));
49	        return ww < 1 ? 1 : (Math.min(ww, weight));
50	    }
51	
52	    @Override
53	    public <T> Invoker<T> select(List<Invoker<T>> invokers, URL url, Invocation invocation) {
54	        if (CollectionUtils.isEmpty(invokers)) {
55	            return null;
56	        }
57	        if (invokers.size() == 1) {
58	            return invokers.get(0);
59	        }
60	        return doSelect(invokers, url, invocation);

60	        return doSelect(invokers, url, invocation);
61	    }
62	
63	    protected abstract <T> Invoker<T> doSelect(List<Invoker<T>> invokers, URL url, Invocation invocation);
64	
65	    /**
66	     * Pick one invoker from a pre-filtered candidate set using weighted random selection.
67	     * Used by load balancers that first narrow the field to a "best" tier (e.g. least-active,
68	     * shortest-response) and then apply the same weighted-random tiebreak.
69	     */
70	    protected static <T> Invoker<T> selectWithWeight(
71	            List<Invoker<T>> invokers,
72	            int[] candidateIndexes,
73	            int candidateCount,
74	            int[] weights,
75	            boolean sameWeight,
76	            int totalWeight) {
77	        if (candidateCount == 1) {
78	            return invokers.get(candidateIndexes[0]);
79	        }
80	        if (!sameWeight && totalWeight > 0) {
81	            int offsetWeight = ThreadLocalRandom.current().nextInt(totalWeight);
82	            for (int i = 0; i < candidateCount; i++) {
83	                int idx = candidateIndexes[i];
84	                offsetWeight -= weights[idx];
85	                if (offsetWeight < 0) {
86	                    return invokers.get(idx);
87	                }
88	            }
89	        }
90	        return invokers.get(candidateIndexes[ThreadLocalRandom.current().nextInt(candidateCount)]);
91	    }
92	
93	    /**
94	     * Get the weight of the invoker's invocation which takes warmup time into account
95	     * if the uptime is within the warmup time, the weight will be reduce proportionally
96	     *
97	     * @param invoker    the invoker
98	     * @param invocation the invocation of this invoker
99	     * @return weight
100	     */
101	    protected int getWeight(Invoker<?> invoker, Invocation invocation) {
102	        int weight;
103	        URL url = invoker.getUrl();
104	        if (invoker instanceof ClusterInvoker) {
105	            url = ((ClusterInvoker<?>) invoker).getRegistryUrl();
106	        }
107	
108	        // Multiple registry scenario, load balance among multiple registries.
109	        if (REGISTRY_SERVICE_REFERENCE_PATH.equals(url.getServiceInterface())) {
110	            weight = url.getParameter(WEIGHT_KEY, DEFAULT_WEIGHT);
111	        } else {
112	            weight = url.getMethodParameter(RpcUtils.getMethodName(invocation), WEIGHT_KEY, DEFAULT_WEIGHT);
113	            if (weight > 0) {
114	                long timestamp = invoker.getUrl().getParameter(TIMESTAMP_KEY, 0L);
115	                if (timestamp > 0L) {
116	                    long uptime = System.currentTimeMillis() - timestamp;
117	                    if (uptime < 0) {
118	                        return 1;
119	                    }
120	                    int warmup = invoker.getUrl().getParameter(WARMUP_KEY, DEFAULT_WARMUP);
121	                    if (uptime > 0 && uptime < warmup) {
122	                        weight = calculateWarmupWeight((int) uptime, warmup, weight);
123	                    }
124	                }
125	            }
126	        }
127	        return Math.max(weight, 0);
128	    }
129	}
