113	                    JSONWriter.Feature.WriteNulls,
114	                    JSONWriter.Feature.NotWriteDefaultValue,
115	                    JSONWriter.Feature.NotWriteHashMapArrayListClassName,
116	                    JSONWriter.Feature.WriteNameAsSymbol);
117	        } else {
118	            bytes = JSONB.toBytes(
119	                    obj,
120	                    JSONWriter.Feature.WriteClassName,
121	                    JSONWriter.Feature.FieldBased,
122	                    JSONWriter.Feature.ReferenceDetection,
123	                    JSONWriter.Feature.WriteNulls,
124	                    JSONWriter.Feature.NotWriteDefaultValue,
125	                    JSONWriter.Feature.NotWriteHashMapArrayListClassName,
126	                    JSONWriter.Feature.WriteNameAsSymbol);
